/* // Savings.js
import { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import UserProfile from './UserProfile';

function Savings() {
  const [email, setEmail] = useState(null);

  useEffect(() => {
    const storedEmail = localStorage.getItem('userEmail');
    setEmail(storedEmail);
  }, []);

  if (email === null) {
    return <p>Loading...</p>;
  } else if (email === undefined || email === '') {
    return <Navigate to="/" />;  // Assuming "/" is your login route

  return <UserProfile email={email} />;
}

export default Savings; */



// UserProfile.js
import { useEffect, useState } from 'react';
import axios from 'axios';

function UserProfile({ email }) {
  const [user, setUser] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const response = await axios.get(`http://localhost:8000/savings/${email}`); // Now this is correct!
        setUser(response.data);
      } catch (err) {
        console.error("API Error:", err);
        setError('Error fetching user data: ' + err.message); // More informative error
      }
    };

    fetchUserData();
  }, [email]);


  if (error) {
    return <p style={{ color: 'red' }}>{error}</p>;
  }

  if (!user) {
    return <p>Loading user data...</p>;
  }

  return (
    <div className="user-profile">
      <h2>User Profile</h2>
      <p><strong>Name:</strong> {user.name}</p>
      <p><strong>Father's Name:</strong> {user.fatherName}</p>
      <p><strong>Mother's Name:</strong> {user.motherName}</p>
      <p><strong>Date of Birth:</strong> {new Date(user.dob).toLocaleDateString()}</p>
      <p><strong>Age:</strong> {user.age}</p>
      <p><strong>Gender:</strong> {user.gender}</p>
      <p><strong>Balance:</strong> ${user.balance.toFixed(2)}</p>
    </div>
  );
}

export default UserProfile;
